func (this *Bitfinex) IsFiat(code any) bool {
	var fiat map[string]any = SafeMapTyped(this.Options, "fiat")
	return (InOp(fiat, code))
}
func (this *Bitfinex) GetCurrencyName(code any) any {
	// temporary fix for transpiler recognition, even though this is in parent class
	if InOp(this.Options["currencyNames"], code) {
		return GetValue(this.Options["currencyNames"], code)
	}
	panic(NotSupported(Add(Add(this.Id+" ", code), " not supported for withdrawal")))
}
func (this *Bitfinex) AmountToPrecision(symbol any, amount any) *string {
	// https://docs.bitfinex.com/docs/introduction#amount-precision
	// The amount field allows up to 8 decimals.
	// Anything exceeding this will be rounded to the 8th decimal.
	var symbolValue *string = this.SafeSymbol(symbol)
	var market map[string]any = this.Market(symbolValue)
	return SafeStringPtr(this.DecimalToPrecision(amount, TRUNCATE, this.SafeValue(market["precision"], "amount"), DECIMAL_PLACES))
}
func (this *Bitfinex) PriceToPrecision(symbol any, price any) *string {
	var symbolValue *string = this.SafeSymbol(symbol)
	var market map[string]any = this.Market(symbolValue)
	var priceValue string = this.DecimalToPrecision(price, ROUND, this.SafeValue(market["precision"], "price"), this.PrecisionMode)
	// https://docs.bitfinex.com/docs/introduction#price-precision
	// The precision level of all trading prices is based on significant figures.
	// All pairs on Bitfinex use up to 5 significant digits and up to 8 decimals (e.g. 1.2345, 123.45, 1234.5, 0.00012345).
	// Prices submit with a precision larger than 5 will be cut by the API.
	return SafeStringPtr(this.DecimalToPrecision(priceValue, TRUNCATE, 8, DECIMAL_PLACES))
}

/**
 * @method
 * @name bitfinex#fetchStatus
 * @description the latest known information on the availability of the exchange API
 * @see https://docs.bitfinex.com/reference/rest-public-platform-status
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [status structure]{@link https://docs.ccxt.com/?id=exchange-status-structure}
 */
func (this *Bitfinex) FetchStatusAsync(optionalArgs ...any) <-chan AsyncResult[Status] {
	ch := make(chan AsyncResult[Status], 1)
	go this.fetchStatusBody(ch, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchStatusBody(ch chan AsyncResult[Status], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	//
	//    [1] // operative
	//    [0] // maintenance
	//
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.PublicGetPlatformStatus(params)
	if r.Err != nil {
		panic(r.Err)
	}
	response := r.Raw
	var statusRaw *string = this.SafeString(response, 0)

	ch <- AsyncResult[Status]{Value: StatusFromMap(map[string]any{
		"status": this.SafeString(map[string]any{
			"0": "maintenance",
			"1": "ok",
		}, statusRaw, statusRaw),
		"updated": nil,
		"eta":     nil,
		"url":     nil,
		"info":    response,
	})}
	return nil
}

/**
 * @method
 * @name bitfinex#fetchMarkets
 * @description retrieves data on all markets for bitfinex
 * @see https://docs.bitfinex.com/reference/rest-public-conf
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Bitfinex) FetchMarketsAsync(optionalArgs ...any) <-chan AsyncResult[[]MarketInterface] {
	ch := make(chan AsyncResult[[]MarketInterface], 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchMarketsBody(ch chan AsyncResult[[]MarketInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var labels []string = []string{"pub:info:pair", "pub:info:pair:futures", "pub:list:pair:securities", "pub:list:pair:margin"}
	var config string = strings.Join(labels, ",")
	var request map[string]any = map[string]any{
		"config": config,
	}

	listEp900 := <-this.PublicGetConfConfig(this.Extend(request, params))
	if listEp900.Err != nil {
		panic(listEp900.Err)
	}
	var response []any = listEp900.Value
	var spotMarketsInfo []any = SafeListTypedDefault(response, 0, []any{})
	var futuresMarketsInfo []any = SafeListTypedDefault(response, 1, []any{})
	var marginIds []any = SafeListTypedDefault(response, 3, []any{})
	var markets []any = this.ArrayConcat(spotMarketsInfo, futuresMarketsInfo)
	var result []any = []any{}
	for i := 0; i < len(markets); i++ {
		var pairObj []any = SafeListTyped(markets, i)
		var id *string = this.SafeStringUpper(pairObj, 0, "")
		var market []any = SafeListTypedDefault(pairObj, 1, []any{})
		var spot bool = true
		var typeVar string
		if strings.Index(*id, "F0") >= 0 {
			spot = false
			typeVar = "swap"
		} else {
			typeVar = "spot"
		}
		var swap bool = (typeVar == "swap")
		var baseId any = nil
		var quoteId any = nil
		if strings.Index(*id, ":") >= 0 {
			var parts []string = strings.Split(*id, ":")
			baseId = parts[0]
			quoteId = func() any {
				if 1 >= 0 && 1 < len(parts) {
					return parts[1]
				}
				return nil
			}()
		} else {
			baseId = func() string {
				if id == nil {
					return ""
				}
				str := *id
				return str[0:min(3, len(str))]
			}()
			quoteId = func() string {
				if id == nil {
					return ""
				}
				str := *id
				return str[3:min(6, len(str))]
			}()
		}
		var base *string = this.SafeCurrencyCode(baseId)
		var quote *string = this.SafeCurrencyCode(quoteId)
		var splitBase []string = strings.Split(*base, "F0")
		var splitQuote []string = strings.Split(*quote, "F0")
		base = this.SafeString(splitBase, 0)
		quote = this.SafeString(splitQuote, 0)
		if (base == nil) || (quote == nil) {
			continue
		}
		var symbol string = *base + "/" + *quote
		// baseId = 'f' + baseId;
		// quoteId = 'f' + quoteId;
		var settle *string = nil
		var settleId *string = nil
		if swap {
			settle = quote
			settleId = quote
			symbol = symbol + ":" + *settle
		}
		var minOrderSizeString *string = this.SafeString(market, 3)
		var maxOrderSizeString *string = this.SafeString(market, 4)
		result = append(result, map[string]any{
			"id":       "t" + *id,
			"symbol":   symbol,
			"base":     base,
			"quote":    quote,
			"settle":   settle,
			"baseId":   baseId,
			"quoteId":  quoteId,
			"settleId": settleId,
			"type":     typeVar,
			"spot":     spot,
			"margin":   (spot && this.InArray(id, marginIds)),
			"swap":     swap,
			"future":   false,
			"option":   false,
			"active":   true,
			"contract": !spot,
			"linear": func() any {
				if swap {
					return true
				}
				return nil
			}(),
			"inverse": func() any {
				if swap {
					return false
				}
				return nil
			}(),
			"contractSize": func() any {
				if swap {
					return this.ParseNumber("1")
				}
				return nil
			}(),
			"expiry":         nil,
			"expiryDatetime": nil,
			"strike":         nil,
			"optionType":     nil,
			"precision": map[string]any{
				"amount": int64(8),
				"price":  int64(5),
			},
			"limits": map[string]any{
				"leverage": map[string]any{
					"min": nil,
					"max": nil,
				},
				"amount": map[string]any{
					"min": this.ParseNumber(minOrderSizeString),
					"max": this.ParseNumber(maxOrderSizeString),
				},
				"price": map[string]any{
					"min": this.ParseNumber("1e-8"),
					"max": nil,
				},
				"cost": map[string]any{
					"min": nil,
					"max": nil,
				},
			},
			"created": nil,
			"info":    market,
		})
	}

	ch <- AsyncResult[[]MarketInterface]{Value: MarketInterfacesFromList(result)}
	return nil
}

/**
 * @method
 * @name bitfinex#fetchCurrencies
 * @description fetches all available currencies on an exchange
 * @see https://docs.bitfinex.com/reference/rest-public-conf
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an associative dictionary of currencies
 */
func (this *Bitfinex) FetchCurrenciesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.fetchCurrenciesBody(ch, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchCurrenciesBody(ch chan AsyncResult[map[string]any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var labels []string = []string{"pub:list:currency", "pub:map:currency:sym", "pub:map:currency:label", "pub:map:currency:unit", "pub:map:currency:undl", "pub:map:currency:pool", "pub:map:currency:explorer", "pub:map:currency:tx:fee", "pub:map:tx:method", "pub:info:tx:status", "pub:list:currency:margin"}
	var config string = strings.Join(labels, ",")
	var request map[string]any = map[string]any{
		"config": config,
	}

	listEp1066 := <-this.PublicGetConfConfig(this.Extend(request, params))
	if listEp1066.Err != nil {
		panic(listEp1066.Err)
	}
	var response []any = listEp1066.Value
	//
	//     [
	//
	//         a list of symbols
	//         ["AAA","ABS","ADA"],
	//
	//         // sym
	//         // maps symbols to their API symbols, BAB > BCH
	//         [
	//             [ "BAB", "BCH" ],
	//             [ "CNHT", "CNHt" ],
	//             [ "DSH", "DASH" ],
	//             [ "IOT", "IOTA" ],
	//             [ "LES", "LEO-EOS" ],
	//             [ "LET", "LEO-ERC20" ],
	//             [ "STJ", "STORJ" ],
	//             [ "TSD", "TUSD" ],
	//             [ "UDC", "USDC" ],
	//             [ "USK", "USDK" ],
	//             [ "UST", "USDt" ],
	//             [ "USTF0", "USDt0" ],
	//             [ "XCH", "XCHF" ],
	//             [ "YYW", "YOYOW" ],
	//             // ...
	//         ],
	//         // label
	//         // verbose friendly names, BNT > Bancor
	//         [
	//             [ "BAB", "Bitcoin Cash" ],
	//             [ "BCH", "Bitcoin Cash" ],
	//             [ "LEO", "Unus Sed LEO" ],
	//             [ "LES", "Unus Sed LEO (EOS)" ],
	//             [ "LET", "Unus Sed LEO (ERC20)" ],
	//             // ...
	//         ],
	//         // unit
	//         // maps symbols to unit of measure where applicable
	//         [
	//             [ "IOT", "Mi|MegaIOTA" ],
	//         ],
	//         // undl
	//         // maps derivatives symbols to their underlying currency
	//         [
	//             [ "USTF0", "UST" ],
	//             [ "BTCF0", "BTC" ],
	//             [ "ETHF0", "ETH" ],
	//         ],
	//         // pool
	//         // maps symbols to underlying network/protocol they operate on
	//         [
	//             [ 'SAN', 'ETH' ], [ 'OMG', 'ETH' ], [ 'AVT', 'ETH' ], [ "EDO", "ETH" ],
	//             [ 'ESS', 'ETH' ], [ 'ATD', 'EOS' ], [ 'ADD', 'EOS' ], [ "MTO", "EOS" ],
	//             [ 'PNK', 'ETH' ], [ 'BAB', 'BCH' ], [ 'WLO', 'XLM' ], [ "VLD", "ETH" ],
	//             [ 'BTT', 'TRX' ], [ 'IMP', 'ETH' ], [ 'SCR', 'ETH' ], [ "GNO", "ETH" ],
	//             // ...
	//         ],
	//         // explorer
	//         // maps symbols to their recognised block explorer URLs
	//         [
	//             [
	//                 "AIO",
	//                 [
	//                     "https://mainnet.aion.network",
	//                     "https://mainnet.aion.network/#/account/VAL",
	//                     "https://mainnet.aion.network/#/transaction/VAL"
	//                 ]
	//             ],
	//             // ...
	//         ],
	//         // fee
	//         // maps currencies to their withdrawal fees
	//         [
	//             ["AAA",[0,0]],
	//             ["ABS",[0,131.3]],
	//             ["ADA",[0,0.3]],
	//         ],
	//         // deposit/withdrawal data
	//         [
	//           ["BITCOIN", 1, 1, null, null, null, null, 0, 0, null, null, 3],
	//           ...
	//         ]
	//     ]
	//
	var networks []any = SafeListTypedDefault(response, 8, []any{})
	var indexed map[string]any = map[string]any{
		"sym":         this.IndexBy(this.SafeList(response, 1, []any{}), 0),
		"label":       this.IndexBy(this.SafeList(response, 2, []any{}), 0),
		"unit":        this.IndexBy(this.SafeList(response, 3, []any{}), 0),
		"undl":        this.IndexBy(this.SafeList(response, 4, []any{}), 0),
		"pool":        this.IndexBy(this.SafeList(response, 5, []any{}), 0),
		"explorer":    this.IndexBy(this.SafeList(response, 6, []any{}), 0),
		"fees":        this.IndexBy(this.SafeList(response, 7, []any{}), 0),
		"networks":    networks,
		"statuses":    this.IndexBy(this.SafeList(response, 9, []any{}), 0),
		"marginables": this.SafeList(response, 10, []any{}),
	}
	var indexedNetworks map[string]any = map[string]any{}
	for i := 0; i < len(networks); i++ {
		var networkObj []any = SafeListTyped(networks, i)
		var networkId *string = this.SafeString(networkObj, 0)
		var valuesList []any = SafeListTyped(networkObj, 1)
		var networkName *string = this.SafeString(valuesList, 0)
		// for GOlang transpiler, do with "safe" method
		var networksList any = this.SafeList(indexedNetworks, networkName, []any{})
		AppendToArray(&networksList, networkId)
		AddElementToObject(indexedNetworks, networkName, networksList)
	}
	var ids []any = SafeListTypedDefault(response, 0, []any{})

	ch <- AsyncResult[map[string]any]{Value: this.ParseCurrenciesCustom(ids, indexed, indexedNetworks)}
	return nil
}
func (this *Bitfinex) ParseCurrenciesCustom(ids []any, indexed map[string]any, indexedNetworks map[string]any) map[string]any {
	var allowedIds []any = []any{}
	for i := 0; i < len(ids); i++ {
		var id *string = this.SafeString(ids, i, "")
		if strings.HasSuffix(*id, "F0") {
			continue
		}
		allowedIds = append(allowedIds, id)
	}
	var result map[string]any = map[string]any{}
	var arr []any = this.ToArray(allowedIds)
	for i := 0; i < len(arr); i++ {
		var parsed any = this.ParseCurrencyCustom(DerefScalar(arr[i]), indexed, indexedNetworks)
		var code *string = this.SafeString(parsed, "code", "")
		AddElementToObject(result, code, parsed)
	}
	return result
}
func (this *Bitfinex) ParseCurrencyCustom(id any, indexed map[string]any, indexedNetworks map[string]any) any {
	var code *string = this.SafeCurrencyCode(id)
	var label []any = SafeListTypedDefault(indexed["label"], id, []any{})
	var name *string = this.SafeString(label, 1)
	var pool []any = SafeListTypedDefault(indexed["pool"], id, []any{})
	var rawType *string = this.SafeString(pool, 1)
	var explorer map[string]any = SafeMapTyped(indexed, "explorer")
	var isCryptoCoin bool = (rawType != nil) || (InOp(explorer, id)) // "hacky" solution
	var typeVar *string = func() *string {
		if isCryptoCoin {
			return SafeStringPtr("crypto")
		}
		return nil
	}()
	var feeValues []any = SafeListTypedDefault(indexed["fees"], id, []any{})
	var fees []any = SafeListTyped(feeValues, 1)
	var fee *float64 = this.SafeNumber(fees, 1)
	var undl []any = SafeListTypedDefault(indexed["undl"], id, []any{})
	var defaultCurrencyPrecision *string = this.SafeString(this.Options, "defaultCurrencyPrecision", "8") // kept here for backward-compatibility
	// numberToString instead of an `as string` cast: the describe() default for this option is the
	// NUMBER 8 (and users may override with numbers too), and the hard cast makes the C# build throw
	// InvalidCastException Int32 to String here, breaking bitfinex loadMarkets entirely in C#
	var precision *string = this.NumberToString(this.HandleOption("fetchCurrencies", "defaultPrecision", defaultCurrencyPrecision))
	var networks map[string]any = map[string]any{}
	var networkIds []any = SafeListTyped(indexedNetworks, id)
	for j := 0; j < len(networkIds); j++ {
		// safeString instead of raw access: the venue config payload can carry numeric
		// network ids, and the raw value flows into toLowerCase and a dictionary key,
		// which hard-casts to string in the C# build and throws InvalidCastException
		var networkId *string = this.SafeString(networkIds, j)
		if networkId == nil {
			continue
		}
		var network *string = this.NetworkIdToCode(networkId, code)
		var dwStatuses []any = SafeListTyped(indexed["statuses"], networkId)
		if network != nil {
			networks[*network] = map[string]any{
				"info":      networkId,
				"id":        strings.ToLower(*networkId),
				"network":   network,
				"active":    nil,
				"deposit":   (this.SafeInteger(dwStatuses, 1) != nil && *this.SafeInteger(dwStatuses, 1) == 1),
				"withdraw":  (this.SafeInteger(dwStatuses, 2) != nil && *this.SafeInteger(dwStatuses, 2) == 1),
				"fee":       nil,
				"precision": nil,
				"limits": map[string]any{
					"withdraw": map[string]any{
						"min": nil,
						"max": nil,
					},
				},
			}
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"id":        id,
		"code":      code,
		"info":      []any{id, label, pool, feeValues, undl},
		"type":      typeVar,
		"name":      name,
		"active":    true,
		"deposit":   nil,
		"withdraw":  nil,
		"fee":       fee,
		"precision": this.ParseNumber(precision),
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"withdraw": map[string]any{
				"min": fee,
				"max": nil,
			},
		},
		"networks": networks,
		"margin":   this.InArray(id, indexed["marginables"]),
	})
}

/**
 * @method
 * @name bitfinex#fetchBalance
 * @description query for balance and get the amount of funds available for trading or funds locked in orders
 * @see https://docs.bitfinex.com/reference/rest-auth-wallets
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Bitfinex) FetchBalanceAsync(optionalArgs ...any) <-chan AsyncResult[Balances] {
	ch := make(chan AsyncResult[Balances], 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchBalanceBody(ch chan AsyncResult[Balances], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// this api call does not return the 'used' amount - use the v1 version instead (which also returns zero balances)
	// there is a difference between this and the v1 api, namely trading wallet is called margin in v2
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var accountsByType map[string]any = SafeMapTyped(this.Options, "v2AccountsByType")
	var requestedType *string = this.SafeString(params, "type", "exchange")
	var accountType *string = this.SafeString(accountsByType, requestedType, requestedType)
	if accountType == nil {
		var keys []string = nil
		if accountsByType != nil {
			keys = make([]string, 0, len(accountsByType))
			for objectKey := range accountsByType {
				keys = append(keys, objectKey)
			}
		}
		panic(ExchangeError(this.Id + " fetchBalance() type parameter must be one of " + strings.Join(keys, ", ")))
	}
	var isDerivative bool = (requestedType != nil && *requestedType == "derivatives")
	var query map[string]any = this.OmitDict(params, "type")

	r1 := <-this.PrivatePostAuthRWallets(query)
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	var balances []any = this.ToArray(response)
	var result map[string]any = map[string]any{
		"info": response,
	}
	for i := 0; i < len(balances); i++ {
		var balance []any = SafeListTyped(balances, i)
		var account map[string]any = this.Account()
		var interest *string = this.SafeString(balance, 3)
		if interest == nil || *interest != "0" {
			account["debt"] = interest
		}
		var typeVar *string = this.SafeString(balance, 0)
		var currencyId *string = this.SafeStringLower(balance, 1, "")
		var isDerivativeCode bool = (currencyId != nil) && (strings.HasSuffix(*currencyId, "f0") == true)
		// this will only filter the derivative codes if the requestedType is 'derivatives'
		var derivativeCondition bool = (!isDerivative || isDerivativeCode)
		if (accountType == typeVar || (accountType != nil && typeVar != nil && *accountType == *typeVar)) && derivativeCondition {
			var code *string = this.SafeCurrencyCode(currencyId)
			account["total"] = this.SafeString(balance, 2)
			account["free"] = this.SafeString(balance, 4)
			if code != nil {
				result[*code] = account
			}
		}
	}

	ch <- AsyncResult[Balances]{Value: BalancesFromMap(this.SafeBalance(result).(map[string]any))}
	return nil
}

/**
 * @method
 * @name bitfinex#transfer
 * @description transfer currency internally between wallets on the same account
 * @see https://docs.bitfinex.com/reference/rest-auth-transfer
 * @param {string} code unified currency code
 * @param {float} amount amount to transfer
 * @param {string} fromAccount account to transfer from
 * @param {string} toAccount account to transfer to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Bitfinex) TransferAsync(code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) <-chan AsyncResult[TransferEntry] {
	ch := make(chan AsyncResult[TransferEntry], 1)
	go this.transferBody(ch, code, amount, fromAccount, toAccount, optionalArgs...)
	return ch
}
func (this *Bitfinex) transferBody(ch chan AsyncResult[TransferEntry], code string, amount any, fromAccount string, toAccount string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	// transferring between derivatives wallet and regular wallet is not documented in their API
	// however we support it in CCXT (from just looking at web inspector)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var accountsByType map[string]any = SafeMapTyped(this.Options, "v2AccountsByType")
	var fromId *string = this.SafeString(accountsByType, fromAccount)
	if fromId == nil {
		var keys []string = nil
		if accountsByType != nil {
			keys = make([]string, 0, len(accountsByType))
			for objectKey := range accountsByType {
				keys = append(keys, objectKey)
			}
		}
		panic(ArgumentsRequired(this.Id + " transfer() fromAccount must be one of " + strings.Join(keys, ", ")))
	}
	var toId *string = this.SafeString(accountsByType, toAccount)
	if toId == nil {
		var keys []string = nil
		if accountsByType != nil {
			keys = make([]string, 0, len(accountsByType))
			for objectKey := range accountsByType {
				keys = append(keys, objectKey)
			}
		}
		panic(ArgumentsRequired(this.Id + " transfer() toAccount must be one of " + strings.Join(keys, ", ")))
	}
	var currency map[string]any = this.Currency(code)
	var fromCurrencyId any = this.ConvertDerivativesId(currency, fromAccount)
	var toCurrencyId any = this.ConvertDerivativesId(currency, toAccount)
	var requestedAmount any = this.CurrencyToPrecision(code, amount)
	// this request is slightly different from v1 fromAccount -> from
	var request map[string]any = map[string]any{
		"amount":      requestedAmount,
		"currency":    fromCurrencyId,
		"currency_to": toCurrencyId,
		"from":        fromId,
		"to":          toId,
	}

	r1 := <-this.PrivatePostAuthWTransfer(this.Extend(request, params))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	//
	//     [
	//         1616451183763,
	//         "acc_tf",
	//         null,
	//         null,
	//         [
	//             1616451183763,
	//             "exchange",
	//             "margin",
	//             null,
	//             "UST",
	//             "UST",
	//             null,
	//             1
	//         ],
	//         null,
	//         "SUCCESS",
	//         "1.0 Tether USDt transfered from Exchange to Margin"
	//     ]
	//
	var error *string = this.SafeString(response, 0)
	if error != nil && *error == "error" {
		var message *string = this.SafeString(response, 2, "")
		// same message as in v1
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, this.Id+" "+*message)
		panic(ExchangeError(this.Id + " " + *message))
	}

	ch <- AsyncResult[TransferEntry]{Value: this.ParseTransfer(map[string]any{
		"result": response,
	}, currency)}
	return nil
}
func (this *Bitfinex) ParseTransfer(transfer any, optionalArgs ...any) TransferEntry {
	//
	// transfer
	//
	//     [
	//         1616451183763,
	//         "acc_tf",
	//         null,
	//         null,
	//         [
	//             1616451183763,
	//             "exchange",
	//             "margin",
	//             null,
	//             "UST",
	//             "UST",
	//             null,
	//             1
	//         ],
	//         null,
	//         "SUCCESS",
	//         "1.0 Tether USDt transfered from Exchange to Margin"
	//     ]
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var result []any = SafeListTyped(transfer, "result")
	var timestamp *int64 = this.SafeInteger(result, 0)
	var info []any = SafeListTyped(result, 4)
	var fromAccount *string = this.SafeString(info, 1)
	var toAccount *string = this.SafeString(info, 2)
	var currencyId *string = this.SafeString(info, 5)
	var status *string = this.SafeString(result, 6)
	return TransferEntryFromMap(map[string]any{
		"id":          nil,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"status":      this.ParseTransferStatus(status),
		"amount":      this.SafeNumber(info, 7),
		"currency":    this.SafeCurrencyCode(currencyId, currency),
		"fromAccount": fromAccount,
		"toAccount":   toAccount,
		"info":        result,
	})
}
func (this *Bitfinex) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"SUCCESS": "ok",
		"ERROR":   "failed",
		"FAILURE": "failed",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bitfinex) ConvertDerivativesId(currency map[string]any, typeVar string) any {
	// there is a difference between this and the v1 api, namely trading wallet is called margin in v2
	// {
	//   "id": "fUSTF0",
	//   "code": "USTF0",
	//   "info": [ 'USTF0', [], [], [], [ "USTF0", "UST" ] ],
	var info []any = SafeListTyped(currency, "info")
	var transferId *string = this.SafeString(info, 0)
	var underlying []any = SafeListTyped(info, 4)
	var currencyId any = nil
	if typeVar == "derivatives" {
		if derefPtr := this.SafeString(underlying, 0, transferId); derefPtr != nil {
			currencyId = *derefPtr
		} else {
			currencyId = nil
		}
		var isDerivativeCode bool = EndsWith(currencyId, "F0")
		if !isDerivativeCode {
			currencyId = Add(currencyId, "F0")
		}
	} else if typeVar != "margin" {
		if derefPtr := this.SafeString(underlying, 1, transferId); derefPtr != nil {
			currencyId = *derefPtr
		} else {
			currencyId = nil
		}
	} else {
		currencyId = transferId
	}
	return currencyId
}

/**
 * @method
 * @name bitfinex#fetchOrderBook
 * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
 * @see https://docs.bitfinex.com/reference/rest-public-book
 * @param {string} symbol unified symbol of the market to fetch the order book for
 * @param {int} [limit] the maximum amount of order book entries to return, bitfinex only allows 1, 25, or 100
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
 */
func (this *Bitfinex) FetchOrderBookAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[OrderBook] {
	ch := make(chan AsyncResult[OrderBook], 1)
	go this.fetchOrderBookBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchOrderBookBody(ch chan AsyncResult[OrderBook], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var precision any = this.HandleOption("fetchOrderBook", "precision", "R0")
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol":    market["id"],
		"precision": precision,
	}
	if limit != nil {
		request["len"] = limit
	}
	var fullRequest map[string]any = this.Extend(request, params)

	listEp1568 := <-this.PublicGetBookSymbolPrecision(fullRequest)
	if listEp1568.Err != nil {
		panic(listEp1568.Err)
	}
	var orderbook []any = listEp1568.Value
	var timestamp int64 = this.Milliseconds()
	var result map[string]any = map[string]any{
		"symbol":    market["symbol"],
		"bids":      []any{},
		"asks":      []any{},
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
		"nonce":     nil,
	}
	var priceIndex int = func() int {
		if this.SafeString(fullRequest, "precision") != nil && *this.SafeString(fullRequest, "precision") == "R0" {
			return 1
		}
		return 0
	}()
	var orders []any = this.ToArray(orderbook)
	for i := 0; i < len(orders); i++ {
		var order any = DerefScalar(orders[i])
		var price *float64 = this.SafeNumber(order, priceIndex)
		var signedAmount *string = this.SafeString(order, 2)
		var amount *string = Precise.StringAbs(signedAmount)
		var side string = "asks"
		if Precise.StringGt(signedAmount, "0") {
			side = "bids"
		}
		retRes122412 := result[side]
		AppendToArray(&retRes122412, []any{price, this.ParseNumber(amount)})
		AddElementToObject(result, side, retRes122412)
	}
	result["bids"] = this.SortBy(result["bids"], 0, true)
	result["asks"] = this.SortBy(result["asks"], 0)

	ch <- AsyncResult[OrderBook]{Value: OrderBookFromMap(result)}
	return nil
}
func (this *Bitfinex) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	//
	// on trading pairs (ex. tBTCUSD)
	//
	//    [
	//            SYMBOL, // this index is not present in singular-ticker
	//            BID,
	//            BID_SIZE,
	//            ASK,
	//            ASK_SIZE,
	//            DAILY_CHANGE,
	//            DAILY_CHANGE_RELATIVE,
	//            LAST_PRICE,
	//            VOLUME,
	//            HIGH,
	//            LOW
	//    ]
	//
	//
	// on funding currencies (ex. fUSD)
	//
	//    [
	//            SYMBOL, // this index is not present in singular-ticker
	//            FRR,
	//            BID,
	//            BID_PERIOD,
	//            BID_SIZE,
	//            ASK,
	//            ASK_PERIOD,
	//            ASK_SIZE,
	//            DAILY_CHANGE,
	//            DAILY_CHANGE_RELATIVE,
	//            LAST_PRICE,
	//            VOLUME,
	//            HIGH,
	//            LOW,
	//            _PLACEHOLDER,
	//            _PLACEHOLDER,
	//            FRR_AMOUNT_AVAILABLE
	//     ]
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var length int = GetArrayLength(ticker)
	// the list shapes (fetchTickers) carry the market id in slot 0, the singular
	// shapes (fetchTicker) do not. safeNumber is not a portable discriminator here:
	// in PHP a non numeric string casts to 0.0 instead of undefined, so 'fUSD' would
	// look like a number and the whole array would be read off by one.
	var firstValue *string = this.SafeString(ticker, 0)
	var hasMarketId bool = (firstValue != nil) && (strings.HasPrefix(*firstValue, "t") || strings.HasPrefix(*firstValue, "f"))
	var isFetchTicker bool = !hasMarketId
	var symbol *string = nil
	var minusIndex int = 0
	if isFetchTicker {
		minusIndex = 1
	}
	var marketId *string = this.SafeString(ticker, 0)
	var marketResolved any = nil
	if isFetchTicker {
		marketResolved = market
	} else {
		marketResolved = this.SafeMarket(marketId, market)
	}
	var isFundingCurrency bool = (length >= 17)
	symbol = this.SafeSymbol(nil, marketResolved)
	var last *string = nil
	var bid *string = nil
	var ask *string = nil
	var change *string = nil
	var percentage *string = nil
	var volume *string = nil
	var high *string = nil
	var low *string = nil
	if isFundingCurrency {
		// per api docs, they are different array type
		last = this.SafeString(ticker, 10-minusIndex)
		bid = this.SafeString(ticker, 2-minusIndex)
		ask = this.SafeString(ticker, 5-minusIndex)
		change = this.SafeString(ticker, 8-minusIndex)
		// funding DAILY_CHANGE_RELATIVE is not change / (last - change), let safeTicker derive percentage
		volume = this.SafeString(ticker, 11-minusIndex)
		high = this.SafeString(ticker, 12-minusIndex)
		low = this.SafeString(ticker, 13-minusIndex)
	} else {
		// on trading pairs (ex. tBTCUSD or tHMSTR:USD)
		last = this.SafeString(ticker, 7-minusIndex)
		bid = this.SafeString(ticker, 1-minusIndex)
		ask = this.SafeString(ticker, 3-minusIndex)
		change = this.SafeString(ticker, 5-minusIndex)
		percentage = this.SafeString(ticker, 6-minusIndex)
		percentage = Precise.StringMul(percentage, "100")
		volume = this.SafeString(ticker, 8-minusIndex)
		high = this.SafeString(ticker, 9-minusIndex)
		low = this.SafeString(ticker, 10-minusIndex)
	}
	return this.SafeTicker(map[string]any{
		"symbol":        symbol,
		"timestamp":     nil,
		"datetime":      nil,
		"high":          high,
		"low":           low,
		"bid":           bid,
		"bidVolume":     nil,
		"ask":           ask,
		"askVolume":     nil,
		"vwap":          nil,
		"open":          nil,
		"close":         last,
		"last":          last,
		"previousClose": nil,
		"change":        change,
		"percentage":    percentage,
		"average":       nil,
		"baseVolume":    volume,
		"quoteVolume":   nil,
		"info":          ticker,
	}, marketResolved)
}

/**
 * @method
 * @name bitfinex#fetchTickers
 * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
 * @see https://docs.bitfinex.com/reference/rest-public-tickers
 * @param {string[]|undefined} symbols unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Bitfinex) FetchTickersAsync(optionalArgs ...any) <-chan AsyncResult[map[string]Ticker] {
	ch := make(chan AsyncResult[map[string]Ticker], 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchTickersBody(ch chan AsyncResult[map[string]Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolsNormalized []string = this.MarketSymbols(symbols)
	var request map[string]any = map[string]any{}
	if symbolsNormalized != nil {
		var ids any = this.MarketIds(symbolsNormalized)
		request["symbols"] = Join(ids, ",")
	} else {
		request["symbols"] = "ALL"
	}

	listEp1762 := <-this.PublicGetTickers(this.Extend(request, params))
	if listEp1762.Err != nil {
		panic(listEp1762.Err)
	}
	var tickers []any = listEp1762.Value

	//
	//     [
	//         // on trading pairs (ex. tBTCUSD)
	//         [
	//             SYMBOL,
	//             BID,
	//             BID_SIZE,
	//             ASK,
	//             ASK_SIZE,
	//             DAILY_CHANGE,
	//             DAILY_CHANGE_RELATIVE,
	//             LAST_PRICE,
	//             VOLUME,
	//             HIGH,
	//             LOW
	//         ],
	//         // on funding currencies (ex. fUSD)
	//         [
	//             SYMBOL,
	//             FRR,
	//             BID,
	//             BID_PERIOD,
	//             BID_SIZE,
	//             ASK,
	//             ASK_PERIOD,
	//             ASK_SIZE,
	//             DAILY_CHANGE,
	//             DAILY_CHANGE_RELATIVE,
	//             LAST_PRICE,
	//             VOLUME,
	//             HIGH,
	//             LOW,
	//             _PLACEHOLDER,
	//             _PLACEHOLDER,
	//             FRR_AMOUNT_AVAILABLE
	//         ],
	//         ...
	//     ]
	//
	ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.ParseTickers(tickers, symbolsNormalized))}
	return nil
}

/**
 * @method
 * @name bitfinex#fetchTicker
 * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
 * @see https://docs.bitfinex.com/reference/rest-public-ticker
 * @param {string} symbol unified symbol of the market to fetch the ticker for
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Bitfinex) FetchTickerAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[Ticker] {
	ch := make(chan AsyncResult[Ticker], 1)
	go this.fetchTickerBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchTickerBody(ch chan AsyncResult[Ticker], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}

	listEp1835 := <-this.PublicGetTickerSymbol(this.Extend(request, params))
	if listEp1835.Err != nil {
		panic(listEp1835.Err)
	}
	var ticker []any = listEp1835.Value

	ch <- AsyncResult[Ticker]{Value: this.ParseTicker(ticker, market)}
	return nil
}
func (this *Bitfinex) ParseTrade(trade any, optionalArgs ...any) Trade {
	//
	// fetchTrades (public)
	//
	//     [
	//         ID,
	//         MTS, // timestamp
	//         AMOUNT,
	//         PRICE
	//     ]
	//
	// fetchMyTrades (private)
	//
	//     [
	//         ID,
	//         PAIR,
	//         MTS_CREATE,
	//         ORDER_ID,
	//         EXEC_AMOUNT,
	//         EXEC_PRICE,
	//         ORDER_TYPE,
	//         ORDER_PRICE,
	//         MAKER,
	//         FEE,
	//         FEE_CURRENCY,
	//         ...
	//     ]
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var tradeList []any = SafeListTypedDefault(trade, "result", []any{})
	var tradeLength int = len(tradeList)
	var isPrivate bool = (tradeLength > 5)
	var id *string = this.SafeString(tradeList, 0)
	var amountIndex int = func() int {
		if isPrivate {
			return 4
		}
		return 2
	}()
	var side string
	var amountString *string = this.SafeString(tradeList, amountIndex)
	var priceIndex int = func() int {
		if isPrivate {
			return 5
		}
		return 3
	}()
	var priceString *string = this.SafeString(tradeList, priceIndex)
	if strings.HasPrefix(*amountString, "-") {
		side = "sell"
		amountString = Precise.StringAbs(amountString)
	} else {
		side = "buy"
	}
	var orderId *string = nil
	var takerOrMaker *string = nil
	var typeVar *string = nil
	var fee map[string]any = nil
	var symbol *string = this.SafeSymbol(nil, market)
	var timestampIndex int = func() int {
		if isPrivate {
			return 2
		}
		return 1
	}()
	var timestamp *int64 = this.SafeInteger(tradeList, timestampIndex)
	if isPrivate {
		var marketId any = func() any {
			if 1 >= 0 && 1 < len(tradeList) {
				return tradeList[1]
			}
			return nil
		}()
		symbol = this.SafeSymbol(marketId)
		orderId = this.SafeString(tradeList, 3)
		var maker *int64 = this.SafeInteger(tradeList, 8)
		takerOrMaker = SafeStringPtr(func() string {
			if maker != nil && *maker == 1 {
				return "maker"
			}
			return "taker"
		}())
		var feeCostString *string = this.SafeString(tradeList, 9)
		feeCostString = Precise.StringNeg(feeCostString)
		var feeCurrencyId *string = this.SafeString(tradeList, 10)
		var feeCurrency *string = this.SafeCurrencyCode(feeCurrencyId)
		fee = map[string]any{
			"cost":     feeCostString,
			"currency": feeCurrency,
		}
		var orderType any = func() any {
			if 6 >= 0 && 6 < len(tradeList) {
				return tradeList[6]
			}
			return nil
		}()
		typeVar = this.SafeString(this.Options["exchangeTypes"], orderType)
	}
	return this.SafeTrade(map[string]any{
		"id":           id,
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       symbol,
		"order":        orderId,
		"side":         side,
		"type":         typeVar,
		"takerOrMaker": takerOrMaker,
		"price":        priceString,
		"amount":       amountString,
		"cost":         nil,
		"fee":          fee,
		"info":         tradeList,
	}, market)
}

/**
 * @method
 * @name bitfinex#fetchTrades
 * @description get the list of most recent trades for a particular symbol
 * @see https://docs.bitfinex.com/reference/rest-public-trades
 * @param {string} symbol unified symbol of the market to fetch trades for
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum amount of trades to fetch, default 120, max 10000
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @param {int} [params.until] the latest time in ms to fetch entries for
 * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
 */
func (this *Bitfinex) FetchTradesAsync(symbol any, optionalArgs ...any) <-chan AsyncResult[[]Trade] {
	ch := make(chan AsyncResult[[]Trade], 1)
	go this.fetchTradesBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchTradesBody(ch chan AsyncResult[[]Trade], symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var since *int64 = GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 2, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(params, "fetchTrades", "paginate", false)
	if paginate {

		r1 := <-this.FetchPaginatedCallDynamicAsync("fetchTrades", symbol, since, limit, paramsPaginate, 10000)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes153619 []any = r1.Value
		if retRes153619 == nil {
			ch <- AsyncResult[[]Trade]{Value: nil}
		} else {
			ch <- AsyncResult[[]Trade]{Value: TradesFromList(retRes153619)}
		}
		return nil
	}
	var market map[string]any = this.Market(symbol)
	var sort string = "-1"
	var request map[string]any = map[string]any{
		"symbol": market["id"],
	}
	if since != nil {
		request["start"] = since
		sort = "1"
	}
	if limit != nil {
		request["limit"] = mathMin(limit, 10000) // default 120, max 10000
	}
	request["sort"] = sort
	requestUntil, paramsUntil := this.HandleUntilOption("end", request, paramsPaginate)

	listEp2013 := <-this.PublicGetTradesSymbolHist(this.Extend(requestUntil, paramsUntil))
	if listEp2013.Err != nil {
		panic(listEp2013.Err)
	}
	var response []any = listEp2013.Value
	//
	//     [
	//         [
	//             ID,
	//             MTS, // timestamp
	//             AMOUNT,
	//             PRICE
	//         ]
	//     ]
	//
	var rawTrades []any = this.ToArray(response)
	var trades []any = this.SortBy(rawTrades, 1)
	var tradesList []any = []any{}
	for i := 0; i < len(trades); i++ {
		tradesList = append(tradesList, map[string]any{
			"result": this.SafeList(trades, i),
		}) // convert to array of dicts to match parseOrder signature
	}

	ch <- AsyncResult[[]Trade]{Value: TradesFromList(this.ParseTrades(tradesList, market, nil, limit))}
	return nil
}

