/**
 * @method
 * @name bitfinex#fetchDepositAddress
 * @description fetch the deposit address for a currency associated with this account
 * @see https://docs.bitfinex.com/reference/rest-auth-deposit-address
 * @param {string} code unified currency code
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
 */
func (this *Bitfinex) FetchDepositAddressAsync(code string, optionalArgs ...any) <-chan AsyncResult[DepositAddress] {
	ch := make(chan AsyncResult[DepositAddress], 1)
	go this.fetchDepositAddressBody(ch, code, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchDepositAddressBody(ch chan AsyncResult[DepositAddress], code string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	// if not provided explicitly we will try to match using the currency name
	var networkParam *string = this.SafeString(params, "network", code)
	var network *string = this.SafeString(this.NetworkAliases, networkParam, networkParam)
	var currencyNetworks map[string]any = SafeMapTyped(currency, "networks")
	var currencyNetwork map[string]any = SafeMapTyped(currencyNetworks, network)
	var networkId *string = this.SafeString(currencyNetwork, "id")
	if networkId == nil {
		panic(ArgumentsRequired(this.Id + " fetchDepositAddress() could not find a network for '" + code + "'. You can specify it by providing the 'network' value inside params"))
	}
	var wallet *string = this.SafeString(params, "wallet", "exchange") // 'exchange', 'margin', 'funding' and also old labels 'exchange', 'trading', 'deposit', respectively
	var paramsOmitted map[string]any = this.OmitDict(params, "network", "wallet")
	var request map[string]any = map[string]any{
		"method":   networkId,
		"wallet":   wallet,
		"op_renew": 0,
	}

	r1 := <-this.PrivatePostAuthWDepositAddress(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	//
	//     [
	//         1582269616687, // MTS Millisecond Time Stamp of the update
	//         "acc_dep", // TYPE Purpose of notification "acc_dep" for account deposit
	//         null, // MESSAGE_ID unique ID of the message
	//         null, // not documented
	//         [
	//             null, // PLACEHOLDER
	//             "BITCOIN", // METHOD Method of deposit
	//             "BTC", // CURRENCY_CODE Currency code of new address
	//             null, // PLACEHOLDER
	//             "1BC9PZqpUmjyEB54uggn8TFKj49zSDYzqG", // ADDRESS
	//             null, // POOL_ADDRESS
	//         ],
	//         null, // CODE null or integer work in progress
	//         "SUCCESS", // STATUS Status of the notification, SUCCESS, ERROR, FAILURE
	//         "success", // TEXT Text of the notification
	//     ]
	//
	var result []any = SafeListTyped(response, 4)
	var poolAddress *string = this.SafeString(result, 5)
	var address *string = func() *string {
		if poolAddress == nil {
			return this.SafeString(result, 4)
		}
		return poolAddress
	}()
	var tag *string = func() *string {
		if poolAddress == nil {
			return nil
		}
		return this.SafeString(result, 4)
	}()
	this.CheckAddress(address)

	ch <- AsyncResult[DepositAddress]{Value: DepositAddressFromMap(map[string]any{
		"currency": code,
		"address":  address,
		"tag":      tag,
		"network":  nil,
		"info":     response,
	})}
	return nil
}
func (this *Bitfinex) ParseTransactionStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"SUCCESS":              "ok",
		"COMPLETED":            "ok",
		"ERROR":                "failed",
		"FAILURE":              "failed",
		"CANCELED":             "canceled",
		"PENDING APPROVAL":     "pending",
		"PENDING":              "pending",
		"PENDING REVIEW":       "pending",
		"PENDING CANCELLATION": "pending",
		"SENDING":              "pending",
		"USER APPROVED":        "pending",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bitfinex) ParseTransaction(transaction any, optionalArgs ...any) Transaction {
	//
	// withdraw
	//
	//     [
	//         1582271520931, // MTS Millisecond Time Stamp of the update
	//         "acc_wd-req", // TYPE Purpose of notification "acc_wd-req" account withdrawal request
	//         null, // MESSAGE_ID unique ID of the message
	//         null, // not documented
	//         [
	//             0, // WITHDRAWAL_ID Unique Withdrawal ID
	//             null, // PLACEHOLDER
	//             "bitcoin", // METHOD Method of withdrawal
	//             null, // PAYMENT_ID Payment ID if relevant
	//             "exchange", // WALLET Sending wallet
	//             1, // AMOUNT Amount of Withdrawal less fee
	//             null, // PLACEHOLDER
	//             null, // PLACEHOLDER
	//             0.0004, // WITHDRAWAL_FEE Fee on withdrawal
	//         ],
	//         null, // CODE null or integer Work in progress
	//         "SUCCESS", // STATUS Status of the notification, it may vary over time SUCCESS, ERROR, FAILURE
	//         "Invalid bitcoin address (abcdef)", // TEXT Text of the notification
	//     ]
	//
	// fetchDepositsWithdrawals
	//
	//     [
	//         13293039, // ID
	//         "ETH", // CURRENCY
	//         "ETHEREUM", // CURRENCY_NAME
	//         null,
	//         null,
	//         1574175052000, // MTS_STARTED
	//         1574181326000, // MTS_UPDATED
	//         null,
	//         null,
	//         "CANCELED", // STATUS
	//         null,
	//         null,
	//         -0.24, // AMOUNT, negative for withdrawals
	//         -0.00135, // FEES
	//         null,
	//         null,
	//         "0x38110e0Fc932CB2BE...........", // DESTINATION_ADDRESS
	//         null,
	//         null,
	//         null,
	//         "0x523ec8945500.....................................", // TRANSACTION_ID
	//         "Purchase of 100 pizzas", // WITHDRAW_TRANSACTION_NOTE, might also be: null
	//     ]
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var transactionLength int = GetArrayLength(transaction)
	var timestamp *int64 = nil
	var updated *int64 = nil
	var code any = nil
	var amount any = nil
	var id any = nil
	var status *string = nil
	var tag *string = nil
	var typeVar *string = nil
	var feeCost *string = nil
	var txid *string = nil
	var addressTo *string = nil
	var network *string = nil
	var comment *string = nil
	if transactionLength == 8 {
		var data []any = SafeListTyped(transaction, 4)
		timestamp = this.SafeInteger(transaction, 0)
		if currency != nil {
			code = DerefScalar(this.SafeString(currency, "code"))
		}
		feeCost = this.SafeString(data, 8)
		if feeCost != nil {
			feeCost = Precise.StringAbs(feeCost)
		}
		if derefPtr := this.SafeNumber(data, 5); derefPtr != nil {
			amount = *derefPtr
		} else {
			amount = nil
		}
		var withdrawId *int64 = this.SafeInteger(data, 0)
		id = withdrawId
		status = SafeStringPtr("ok")
		if withdrawId != nil && *withdrawId == 0 {
			id = nil
			status = SafeStringPtr("failed")
		}
		tag = this.SafeString(data, 3)
		typeVar = SafeStringPtr("withdrawal")
		var networkId *string = this.SafeString(data, 2)
		network = this.NetworkIdToCode(strings.ToUpper(*networkId), code) // withdraw returns in lowercase
	} else if transactionLength == 22 {
		if derefPtr := this.SafeString(transaction, 0); derefPtr != nil {
			id = *derefPtr
		} else {
			id = nil
		}
		var currencyId *string = this.SafeString(transaction, 1)
		if derefPtr := this.SafeCurrencyCode(currencyId, currency); derefPtr != nil {
			code = *derefPtr
		} else {
			code = nil
		}
		var networkId *string = this.SafeString(transaction, 2)
		network = this.NetworkIdToCode(networkId, code)
		timestamp = this.SafeInteger(transaction, 5)
		updated = this.SafeInteger(transaction, 6)
		status = this.ParseTransactionStatus(this.SafeString(transaction, 9))
		var signedAmount *string = this.SafeString(transaction, 12)
		amount = Precise.StringAbs(signedAmount)
		if signedAmount != nil {
			if Precise.StringLt(signedAmount, "0") {
				typeVar = SafeStringPtr("withdrawal")
			} else {
				typeVar = SafeStringPtr("deposit")
			}
		}
		feeCost = this.SafeString(transaction, 13)
		if feeCost != nil {
			feeCost = Precise.StringAbs(feeCost)
		}
		addressTo = this.SafeString(transaction, 16)
		txid = this.SafeString(transaction, 20)
		comment = this.SafeString(transaction, 21)
	}
	return TransactionFromMap(map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        txid,
		"type":        typeVar,
		"currency":    code,
		"network":     network,
		"amount":      this.ParseNumber(amount),
		"status":      status,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"address":     addressTo,
		"addressFrom": nil,
		"addressTo":   addressTo,
		"tag":         tag,
		"tagFrom":     nil,
		"tagTo":       tag,
		"updated":     updated,
		"comment":     comment,
		"internal":    nil,
		"fee": map[string]any{
			"currency": code,
			"cost":     this.ParseNumber(feeCost),
			"rate":     nil,
		},
	})
}

/**
 * @method
 * @name bitfinex#fetchTradingFees
 * @description fetch the trading fees for multiple markets
 * @see https://docs.bitfinex.com/reference/rest-auth-summary
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a dictionary of [fee structures]{@link https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
 */
func (this *Bitfinex) FetchTradingFeesAsync(optionalArgs ...any) <-chan AsyncResult[map[string]TradingFeeInterface] {
	ch := make(chan AsyncResult[map[string]TradingFeeInterface], 1)
	go this.fetchTradingFeesBody(ch, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchTradingFeesBody(ch chan AsyncResult[map[string]TradingFeeInterface], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}

	r1 := <-this.PrivatePostAuthRSummary(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	//
	//      Response Spec:
	//      [
	//         PLACEHOLDER,
	//         PLACEHOLDER,
	//         PLACEHOLDER,
	//         PLACEHOLDER,
	//         [
	//            [
	//             MAKER_FEE,
	//             MAKER_FEE,
	//             MAKER_FEE,
	//             PLACEHOLDER,
	//             PLACEHOLDER,
	//             DERIV_REBATE
	//            ],
	//            [
	//             TAKER_FEE_TO_CRYPTO,
	//             TAKER_FEE_TO_STABLE,
	//             TAKER_FEE_TO_FIAT,
	//             PLACEHOLDER,
	//             PLACEHOLDER,
	//             DERIV_TAKER_FEE
	//            ]
	//         ],
	//         PLACEHOLDER,
	//         PLACEHOLDER,
	//         PLACEHOLDER,
	//         PLACEHOLDER,
	//         {
	//             LEO_LEV,
	//             LEO_AMOUNT_AVG
	//         }
	//     ]
	//
	//      Example response:
	//
	//     [
	//         null,
	//         null,
	//         null,
	//         null,
	//         [
	//          [ 0.001, 0.001, 0.001, null, null, 0.0002 ],
	//          [ 0.002, 0.002, 0.002, null, null, 0.00065 ]
	//         ],
	//         [
	//          [
	//              {
	//              "curr": "Total (USD)",
	//              "vol": "0",
	//              "vol_safe": "0",
	//              "vol_maker": "0",
	//              "vol_BFX": "0",
	//              "vol_BFX_safe": "0",
	//              "vol_BFX_maker": "0"
	//              }
	//          ],
	//          {},
	//          0
	//         ],
	//         [ null, {}, 0 ],
	//         null,
	//         null,
	//         { leo_lev: "0", leo_amount_avg: "0" }
	//     ]
	//
	var result map[string]any = map[string]any{}
	var fiat map[string]any = SafeMapTyped(this.Options, "fiat")
	var feeData []any = SafeListTyped(response, 4)
	var makerData []any = SafeListTyped(feeData, 0)
	var takerData []any = SafeListTyped(feeData, 1)
	var makerFee *float64 = this.SafeNumber(makerData, 0)
	var makerFeeFiat *float64 = this.SafeNumber(makerData, 2)
	var makerFeeDeriv *float64 = this.SafeNumber(makerData, 5)
	var takerFee *float64 = this.SafeNumber(takerData, 0)
	var takerFeeFiat *float64 = this.SafeNumber(takerData, 2)
	var takerFeeDeriv *float64 = this.SafeNumber(takerData, 5)
	for i := 0; i < len(this.Symbols); i++ {
		var symbol *string = this.SafeString(this.Symbols, i, "")
		var market map[string]any = this.Market(symbol)
		var fee map[string]any = map[string]any{
			"info":       response,
			"symbol":     symbol,
			"percentage": true,
			"tierBased":  true,
		}
		if InOp(fiat, market["quote"]) {
			fee["maker"] = makerFeeFiat
			fee["taker"] = takerFeeFiat
		} else if market["contract"] == true {
			fee["maker"] = makerFeeDeriv
			fee["taker"] = takerFeeDeriv
		} else {
			fee["maker"] = makerFee
			fee["taker"] = takerFee
		}
		if symbol != nil {
			result[*symbol] = fee
		}
	}

	ch <- AsyncResult[map[string]TradingFeeInterface]{Value: TradingFeeInterfaceMapFromMap(result)}
	return nil
}

/**
 * @method
 * @name bitfinex#fetchDepositsWithdrawals
 * @description fetch history of deposits and withdrawals
 * @see https://docs.bitfinex.com/reference/movement-info
 * @see https://docs.bitfinex.com/reference/rest-auth-movements
 * @param {string} [code] unified currency code for the currency of the deposit/withdrawals, default is undefined
 * @param {int} [since] timestamp in ms of the earliest deposit/withdrawal, default is undefined
 * @param {int} [limit] max number of deposit/withdrawals to return, default is undefined
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a list of [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Bitfinex) FetchDepositsWithdrawalsAsync(optionalArgs ...any) <-chan AsyncResult[[]Transaction] {
	ch := make(chan AsyncResult[[]Transaction], 1)
	go this.fetchDepositsWithdrawalsBody(ch, optionalArgs...)
	return ch
}
func (this *Bitfinex) fetchDepositsWithdrawalsBody(ch chan AsyncResult[[]Transaction], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = nil
	var request map[string]any = map[string]any{}
	if since != nil {
		request["start"] = since
	}
	if limit != nil {
		request["limit"] = limit // max 1000
	}
	var response []any = nil
	if code != nil {
		currency = this.Currency(code)
		request["currency"] = currency["id"]

		listEp3589 := <-this.PrivatePostAuthRMovementsCurrencyHist(this.Extend(request, params))
		if listEp3589.Err != nil {
			panic(listEp3589.Err)
		}
		var currencyMovements []any = listEp3589.Value
		response = this.ToArray(currencyMovements)
	} else {

		listEp3593 := <-this.PrivatePostAuthRMovementsHist(this.Extend(request, params))
		if listEp3593.Err != nil {
			panic(listEp3593.Err)
		}
		var movements []any = listEp3593.Value
		response = this.ToArray(movements)
	}

	//
	//     [
	//         [
	//             13293039, // ID
	//             "ETH", // CURRENCY
	//             "ETHEREUM", // CURRENCY_NAME
	//             null,
	//             null,
	//             1574175052000, // MTS_STARTED
	//             1574181326000, // MTS_UPDATED
	//             null,
	//             null,
	//             "CANCELED", // STATUS
	//             null,
	//             null,
	//             -0.24, // AMOUNT, negative for withdrawals
	//             -0.00135, // FEES
	//             null,
	//             null,
	//             "0x38110e0Fc932CB2BE...........", // DESTINATION_ADDRESS
	//             null,
	//             null,
	//             null,
	//             "0x523ec8945500.....................................", // TRANSACTION_ID
	//             "Purchase of 100 pizzas", // WITHDRAW_TRANSACTION_NOTE, might also be: null
	//         ]
	//     ]
	//
	ch <- AsyncResult[[]Transaction]{Value: TransactionsFromList(this.ParseTransactions(response, currency, since, limit))}
	return nil
}

/**
 * @method
 * @name bitfinex#withdraw
 * @description make a withdrawal
 * @see https://docs.bitfinex.com/reference/rest-auth-withdraw
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.tag] memo / destination tag, required for currencies in options['withdrawTagRequiredCurrencies']
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *Bitfinex) WithdrawAsync(code string, amount any, address any, optionalArgs ...any) <-chan AsyncResult[Transaction] {
	ch := make(chan AsyncResult[Transaction], 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *Bitfinex) withdrawBody(ch chan AsyncResult[Transaction], code string, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	tag, paramsWithdrawTag := this.HandleParamString(params, "tag")
	this.CheckAddress(address)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var currency map[string]any = this.Currency(code)
	// if not provided explicitly we will try to match using the currency name
	var networkParam *string = this.SafeString(paramsWithdrawTag, "network", code)
	var network *string = this.SafeString(this.NetworkAliases, networkParam, networkParam)
	var paramsOmitted map[string]any = this.OmitDict(paramsWithdrawTag, "network")
	var currencyNetworks map[string]any = SafeMapTyped(currency, "networks")
	var currencyNetwork map[string]any = SafeMapTyped(currencyNetworks, network)
	var networkId *string = this.SafeString(currencyNetwork, "id")
	if networkId == nil {
		panic(ArgumentsRequired(this.Id + " withdraw() could not find a network for '" + code + "'. You can specify it by providing the 'network' value inside params"))
	}
	var wallet *string = this.SafeString(paramsOmitted, "wallet", "exchange") // 'exchange', 'margin', 'funding' and also old labels 'exchange', 'trading', 'deposit', respectively
	var paramsOmitted2 map[string]any = this.OmitDict(paramsOmitted, "network", "wallet")
	var request map[string]any = map[string]any{
		"method":  networkId,
		"wallet":  wallet,
		"amount":  this.NumberToString(amount),
		"address": address,
	}
	if tag != nil {
		request["payment_id"] = tag
	}
	var withdrawOptions map[string]any = SafeMapTyped(this.Options, "withdraw")
	var includeFee *bool = this.SafeBool(withdrawOptions, "includeFee", false)
	if includeFee != nil && *includeFee {
		request["fee_deduct"] = 1
	}

	r1 := <-this.PrivatePostAuthWWithdraw(this.Extend(request, paramsOmitted2))
	if r1.Err != nil {
		panic(r1.Err)
	}
	response := r1.Raw
	//
	//     [
	//         1582271520931, // MTS Millisecond Time Stamp of the update
	//         "acc_wd-req", // TYPE Purpose of notification "acc_wd-req" account withdrawal request
	//         null, // MESSAGE_ID unique ID of the message
	//         null, // not documented
	//         [
	//             0, // WITHDRAWAL_ID Unique Withdrawal ID
	//             null, // PLACEHOLDER
	//             "bitcoin", // METHOD Method of withdrawal
	//             null, // PAYMENT_ID Payment ID if relevant
	//             "exchange", // WALLET Sending wallet
	//             1, // AMOUNT Amount of Withdrawal less fee
	//             null, // PLACEHOLDER
	//             null, // PLACEHOLDER
	//             0.0004, // WITHDRAWAL_FEE Fee on withdrawal
	//         ],
	//         null, // CODE null or integer Work in progress
	//         "SUCCESS", // STATUS Status of the notification, it may vary over time SUCCESS, ERROR, FAILURE
	//         "Invalid bitcoin address (abcdef)", // TEXT Text of the notification
	//     ]
	//
	// in case of failure:
	//
	//     [
	//         "error",
	//         10001,
	//         "Momentary balance check. Please wait few seconds and try the transfer again."
	//     ]
	//
	var statusMessage *string = this.SafeString(response, 0)
	if statusMessage != nil && *statusMessage == "error" {
		var feedback *string = SafeStringPtr(Add(this.Id+" ", response))
		var message *string = this.SafeString(response, 2, "")
		// same message as in v1
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		panic(ExchangeError(feedback))
	}
	var text *string = this.SafeString(response, 7)
	if text == nil || *text != "success" {
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], text, text)
	}

	ch <- AsyncResult[Transaction]{Value: this.ParseTransaction(response, currency)}
	return nil
}

